# Auditree activity agent __AGENT_VERSION__ -- generated by Odoo (xn_activity).
# Runs hidden in the signed-in user's session. Every 15 seconds it records
# whether the user is active, idle or locked and which program is in front
# (process name only). Every 5 minutes it sends the totals to Odoo.
# Nothing else is collected: no window titles, URLs, keystrokes or screens.
# Do not edit: download a new installer from Odoo > Employees > Activity >
# Agent Setup instead.

$ErrorActionPreference = 'Stop'
$ServerUrl     = '__SERVER_URL__'
$ApiKey        = '__API_KEY__'
$IdleSeconds   = __IDLE_SECONDS__
$AgentVersion  = '__AGENT_VERSION__'
$SampleSeconds = 15
$SlotMinutes   = 5
$MaxPerPost    = 500
$MaxQueue      = 20000          # about 2 weeks of slots
$MaxLogBytes   = 512KB

# --- one copy per user session ------------------------------------------
$created = $false
$mutex = New-Object System.Threading.Mutex($true, 'Local\XnActivityAgent', [ref]$created)
if (-not $created) { exit 0 }

$Dir = Join-Path $env:LOCALAPPDATA 'XnActivity'
if (-not (Test-Path $Dir)) { New-Item -ItemType Directory -Path $Dir | Out-Null }
$QueueFile = Join-Path $Dir 'queue.json'
$LogFile   = Join-Path $Dir 'agent.log'

function Write-Log([string]$msg) {
    try {
        if ((Test-Path $LogFile) -and (Get-Item $LogFile).Length -gt $MaxLogBytes) {
            Move-Item $LogFile "$LogFile.1" -Force
        }
        $line = '{0} {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
        Add-Content -Path $LogFile -Value $line -Encoding ASCII
    } catch { }
}

# PowerShell 5.1 on older .NET does not offer TLS 1.2 by default.
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
[Net.WebRequest]::DefaultWebProxy.Credentials = [Net.CredentialCache]::DefaultNetworkCredentials

Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class XnActivityNative {
    [StructLayout(LayoutKind.Sequential)]
    struct LASTINPUTINFO { public uint cbSize; public uint dwTime; }
    [DllImport("user32.dll")] static extern bool GetLastInputInfo(ref LASTINPUTINFO plii);
    [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
    public static uint IdleSeconds() {
        LASTINPUTINFO l = new LASTINPUTINFO();
        l.cbSize = (uint)Marshal.SizeOf(l);
        if (!GetLastInputInfo(ref l)) return 0;
        return unchecked((uint)Environment.TickCount - l.dwTime) / 1000;
    }
    public static uint ForegroundPid() {
        IntPtr h = GetForegroundWindow();
        if (h == IntPtr.Zero) return 0;
        uint pid;
        GetWindowThreadProcessId(h, out pid);
        return pid;
    }
}
'@

# --- identity -------------------------------------------------------------
$Upn = ''
try {
    $u = (& whoami.exe /upn 2>$null)
    if ($LASTEXITCODE -eq 0 -and $u -match '@') { $Upn = ([string]$u).Trim() }
} catch { }
$Login = $env:USERNAME
$Device = $env:COMPUTERNAME
$SessionId = (Get-Process -Id $PID).SessionId

function Test-Locked {
    $ui = @(Get-Process -Name LogonUI -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq $SessionId })
    return ($ui.Count -gt 0)
}

# Windows records, per app, when it last started and stopped using the
# microphone (Settings > Privacy > Microphone reads the same keys). A start
# with no stop means it is in use right now: a Teams/Zoom call, a phone call
# in the browser. Only checked when there is no keyboard or mouse input.
$MicKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\microphone'
function Test-MicInUse {
    $keys = @(Get-ChildItem $MicKey -ErrorAction SilentlyContinue) + @(Get-ChildItem "$MicKey\NonPackaged" -ErrorAction SilentlyContinue)
    foreach ($k in $keys) {
        $v = Get-ItemProperty -Path $k.PSPath -ErrorAction SilentlyContinue
        if ($v -and $v.LastUsedTimeStart -and $v.LastUsedTimeStop -eq 0) { return $true }
    }
    return $false
}

function Get-ForegroundApp {
    $p = [XnActivityNative]::ForegroundPid()
    if ($p -eq 0) { return 'unknown' }
    try { return (Get-Process -Id $p -ErrorAction Stop).ProcessName.ToLower() } catch { return 'unknown' }
}

function Get-SlotStart([datetime]$t) {
    $m = $t.Minute - ($t.Minute % $SlotMinutes)
    return New-Object DateTime($t.Year, $t.Month, $t.Day, $t.Hour, $m, 0, [DateTimeKind]::Local)
}

function Format-Start([datetime]$t) {
    return ([DateTimeOffset]$t).ToString("yyyy-MM-dd'T'HH:mm:sszzz")
}

# --- queue ----------------------------------------------------------------
$Queue = New-Object System.Collections.ArrayList
if (Test-Path $QueueFile) {
    try {
        $saved = Get-Content -Path $QueueFile -Raw | ConvertFrom-Json
        foreach ($s in @($saved)) { if ($s) { [void]$Queue.Add($s) } }
    } catch { Write-Log "queue file unreadable, starting empty: $_" }
}

function Save-Queue {
    while ($Queue.Count -gt $MaxQueue) { $Queue.RemoveAt(0) }
    try {
        $json = ConvertTo-Json -InputObject @($Queue.ToArray()) -Depth 3 -Compress
        Set-Content -Path "$QueueFile.tmp" -Value $json -Encoding ASCII
        Move-Item "$QueueFile.tmp" $QueueFile -Force
    } catch { Write-Log "could not save queue: $_" }
}

function Send-Queue {
    # Always posts once (a heartbeat when the queue is empty), then keeps
    # going while full batches go through.
    do {
        $n = [Math]::Min($Queue.Count, $MaxPerPost)
        $batch = @()
        if ($n -gt 0) { $batch = $Queue.GetRange(0, $n).ToArray() }
        $body = @{
            upn = $Upn; login = $Login; device = $Device; agent = $AgentVersion
            sent_at = Format-Start (Get-Date)
            slots = @($batch)
        }
        $json = ConvertTo-Json -InputObject $body -Depth 4 -Compress
        try {
            $resp = Invoke-RestMethod -Method Post -Uri "$ServerUrl/xn_activity/ingest" `
                -Headers @{ 'X-Activity-Key' = $ApiKey } -ContentType 'application/json' `
                -Body ([Text.Encoding]::UTF8.GetBytes($json)) -UseBasicParsing -TimeoutSec 30
        } catch {
            Write-Log "send failed ($($Queue.Count) queued): $($_.Exception.Message)"
            return
        }
        if ($n -gt 0) { $Queue.RemoveRange(0, $n); Save-Queue }
        if ($resp.idle_seconds -and [int]$resp.idle_seconds -gt 0) { $script:IdleSeconds = [int]$resp.idle_seconds }
    } while ($n -eq $MaxPerPost -and $Queue.Count -gt 0)
}

# --- main loop ------------------------------------------------------------
Write-Log "agent $AgentVersion started for $Login ($Upn) on $Device"
$Current = @{}                   # app -> @{active; idle; locked}
$CurrentSlot = Get-SlotStart (Get-Date)
$LastTick = Get-Date
Send-Queue

while ($true) {
    Start-Sleep -Seconds $SampleSeconds
    $now = Get-Date
    $gap = ($now - $LastTick).TotalSeconds
    $LastTick = $now

    $slot = Get-SlotStart $now
    if ($slot -ne $CurrentSlot) {
        foreach ($app in $Current.Keys) {
            $c = $Current[$app]
            [void]$Queue.Add([pscustomobject]@{
                start = Format-Start $CurrentSlot; app = $app
                active = [Math]::Min($c.active, 300); idle = [Math]::Min($c.idle, 300)
                locked = [Math]::Min($c.locked, 300)
            })
        }
        $Current = @{}
        $CurrentSlot = $slot
        Save-Queue
        Send-Queue
    }

    # A long gap means the laptop slept: count nothing for it.
    if ($gap -gt ($SampleSeconds * 4)) { continue }

    try {
        if (Test-Locked) {
            $app = 'lockscreen'; $state = 'locked'
        } else {
            $app = Get-ForegroundApp
            if ($app -eq 'lockapp') { $state = 'locked' }
            elseif ([XnActivityNative]::IdleSeconds() -ge $IdleSeconds) {
                # No input, but on a call: that is work, not idle.
                if (Test-MicInUse) { $state = 'active' } else { $state = 'idle' }
            }
            else { $state = 'active' }
        }
        if (-not $Current.ContainsKey($app)) { $Current[$app] = @{ active = 0; idle = 0; locked = 0 } }
        $Current[$app][$state] += $SampleSeconds
    } catch {
        Write-Log "sample failed: $_"
    }
}
